import { hexLine, type AxialCoord } from "./hex.ts";
import {
  createAmbientSignal,
  createBroadcastSignal,
  createOriginSignal,
  createPathSignal,
  type SignalTarget,
  type TopologySignal,
} from "./SignalEngine.ts";

export type SignalPolicyKind = "ambient" | "broadcast" | "origin" | "path";

export interface SignalPolicyContext {
  now: number;
  origin: AxialCoord;
  previous?: AxialCoord | null;
  current?: AxialCoord | null;
  related?: SignalTarget[];
  radius?: number;
  maxRadius?: number;
  transitionSpeed?: number;
  resolveRoute?: (from: AxialCoord, to: AxialCoord) => AxialCoord[];
}

export interface SignalPolicyOptions {
  transitionSpeed?: number;
}

export interface SignalEvent {
  kind: SignalPolicyKind;
  signals: TopologySignal[];
}

export interface SignalPolicy {
  onSceneLoad(context: SignalPolicyContext): SignalEvent[];
  onHover(context: SignalPolicyContext): SignalEvent[];
  onFocus(context: SignalPolicyContext): SignalEvent[];
  onSelect(context: SignalPolicyContext): SignalEvent[];
  onNavigate(context: SignalPolicyContext): SignalEvent[];
  onRevealRelationships(context: SignalPolicyContext): SignalEvent[];
}

function createAmbientEvent(context: SignalPolicyContext): SignalEvent {
  const transitionSpeed = Math.max(0.25, context.transitionSpeed ?? 1);

  return {
    kind: "ambient",
    signals: [
      createAmbientSignal(context.origin, {
        startedAt: context.now,
        duration: Math.round(2800 / transitionSpeed),
        intensity: 0.16,
        radius: Math.max(5, context.maxRadius ?? context.radius ?? 5),
      }),
    ],
  };
}

function createBroadcastEvent(context: SignalPolicyContext): SignalEvent {
  const transitionSpeed = Math.max(0.25, context.transitionSpeed ?? 1);
  const radius = Math.max(6, (context.maxRadius ?? context.radius ?? 6) + 2);

  return {
    kind: "broadcast",
    signals: [
      createBroadcastSignal(context.origin, {
        startedAt: context.now,
        duration: Math.round(1800 / transitionSpeed),
        intensity: 0.88,
        radius,
      }),
    ],
  };
}

function createOriginEvent(context: SignalPolicyContext): SignalEvent {
  const transitionSpeed = Math.max(0.25, context.transitionSpeed ?? 1);

  return {
    kind: "origin",
    signals: [
      createOriginSignal(context.origin, context.related ?? [], {
        startedAt: context.now,
        duration: Math.round(1800 / transitionSpeed),
        intensity: 1,
      }),
    ],
  };
}

function createPathEvent(context: SignalPolicyContext): SignalEvent | null {
  if (!context.previous || !context.current) {
    return null;
  }

  const transitionSpeed = Math.max(0.25, context.transitionSpeed ?? 1);
  const path = context.resolveRoute?.(context.previous, context.current) ?? hexLine(context.previous, context.current);
  const pathSignal = createPathSignal(path, {
    startedAt: context.now,
    duration: Math.round(2400 / transitionSpeed),
    intensity: 0.95,
  });

  if (!pathSignal) {
    return null;
  }

  return {
    kind: "path",
    signals: [pathSignal],
  };
}

function createRelationshipRevealEvent(context: SignalPolicyContext): SignalEvent[] {
  const originEvent = createOriginEvent(context);
  const pathEvents: SignalEvent[] = [];
  const transitionSpeed = Math.max(0.25, context.transitionSpeed ?? 1);

  for (const target of (context.related ?? []).slice(0, 2)) {
    const path = context.resolveRoute?.(context.origin, target) ?? hexLine(context.origin, target);
    const pathSignal = createPathSignal(path, {
      startedAt: context.now,
      duration: Math.round(2200 / transitionSpeed),
      intensity: 0.92,
      targets: [target],
    });

    if (pathSignal) {
      pathEvents.push({
        kind: "path",
        signals: [pathSignal],
      });
    }
  }

  return [originEvent, ...pathEvents];
}

export function collectSignalEvents(events: SignalEvent[]) {
  return events.flatMap((event) => event.signals).filter(Boolean);
}

export function createDefaultSignalPolicy(options: SignalPolicyOptions = {}): SignalPolicy {
  const transitionSpeed = Math.max(0.25, options.transitionSpeed ?? 1.35);

  return {
    onSceneLoad(context) {
      return [createAmbientEvent({ ...context, transitionSpeed })];
    },
    onHover() {
      return [];
    },
    onFocus(context) {
      return [
        createAmbientEvent({ ...context, transitionSpeed }),
        createBroadcastEvent({ ...context, transitionSpeed }),
      ];
    },
    onSelect(context) {
      return [
        createAmbientEvent({ ...context, transitionSpeed }),
        createOriginEvent({ ...context, transitionSpeed }),
      ];
    },
    onNavigate(context) {
      const pathEvent = createPathEvent({ ...context, transitionSpeed });
      if (!pathEvent) {
        return [createAmbientEvent({ ...context, transitionSpeed })];
      }

      return [createAmbientEvent({ ...context, transitionSpeed }), pathEvent];
    },
    onRevealRelationships(context) {
      return [
        createAmbientEvent({ ...context, transitionSpeed }),
        ...createRelationshipRevealEvent({ ...context, transitionSpeed }),
      ];
    },
  };
}
